/* Замена tilda-animation-2.0 для стенда motion.mjs (fixtures/motion/tilda.html), не код Tilda: страница проявляется
   (#allrecords opacity 0 → 1), служебная .t-mbfix сдвигается; появления .t-animate — класс t-animate_started при входе
   в экран, задержка data-animate-delay — transition-delay. На ширине < 1200 класс t-animate снимается у всех, кроме
   data-animate-mobile="y" (как t_animate__checkMobile у Tilda): на телефоне появлений нет. */
(function () {
  var root = document.getElementById('allrecords');
  requestAnimationFrame(function () { root.style.opacity = '1'; var m = document.querySelector('.t-mbfix'); if (m) m.style.transform = 'translateX(1px)'; });
  var narrow = window.innerWidth < 1200;
  var els = [].slice.call(document.querySelectorAll('.t-animate'));
  els.forEach(function (el) {
    if (narrow && el.getAttribute('data-animate-mobile') !== 'y') { el.classList.remove('t-animate'); return; }
    var d = parseFloat(el.getAttribute('data-animate-delay') || '0');
    if (d) el.style.transitionDelay = d + 's';
  });
  var io = new IntersectionObserver(function (list) {
    list.forEach(function (e) { if (e.isIntersecting) { e.target.classList.add('t-animate_started'); io.unobserve(e.target); } });
  });
  els.forEach(function (el) { if (el.classList.contains('t-animate')) io.observe(el); });
})();
